"use strict";

const http = require("http");
const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const NAV_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "identity",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? String(u).replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(headers) {
    const lines = headers && headers["set-cookie"];
    if (!Array.isArray(lines)) return;
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
  get(k) {
    return this.map.get(k);
  }
}

function requestOnce(urlStr, jar, extraHeaders) {
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(urlStr);
    } catch {
      reject(new Error("Invalid URL: " + urlStr));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    const req = lib.request(
      parsed,
      {
        method: "GET",
        headers: { ...NAV_HEADERS, cookie: jar.toString(), ...(extraHeaders || {}) },
        timeout: 45000,
      },
      (res) => {
        jar.absorb(res.headers);
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            finalUrl: urlStr,
            text: Buffer.concat(chunks).toString("utf8"),
          })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
    req.end();
  });
}

async function fetchText(url, jar, headers, maxRedirects = 8) {
  let current = url;
  for (let i = 0; i <= maxRedirects; i++) {
    const res = await requestOnce(current, jar, headers);
    const location = res.headers && res.headers.location;
    if (res.status >= 300 && res.status < 400 && location && i < maxRedirects) {
      current = new URL(location, current).toString();
      continue;
    }
    return { status: res.status, finalUrl: current, text: res.text };
  }
  return { status: 0, finalUrl: current, text: "" };
}

function relayResponses(html) {
  const out = [];
  const re =
    /<script[^>]*data-relay-completed-request[^>]*>([\s\S]*?)<\/script>/g;
  let m;
  while ((m = re.exec(html))) {
    const body = m[1];
    const open = body.indexOf("(");
    const close = body.lastIndexOf(")");
    if (open < 0 || close <= open) continue;
    const inner = body.slice(open + 1, close);
    let i = inner.indexOf('"') + 1;
    let esc = false;
    let end = -1;
    for (; i < inner.length; i++) {
      const c = inner[i];
      if (esc) { esc = false; continue; }
      if (c === "\\") { esc = true; continue; }
      if (c === '"') { end = i; break; }
    }
    if (end < 0) continue;
    const rest = inner.slice(end + 1).trim().replace(/^,/, "").trim();
    try {
      out.push(JSON.parse(rest));
    } catch {

    }
  }
  return out;
}

function findPinObject(node, depth) {
  if (!node || typeof node !== "object" || depth > 10) return null;
  if (
    node.__typename === "PinResponse" &&
    node.data &&
    (node.data.images_orig || node.data.images_736x)
  ) {
    return node.data;
  }
  for (const v of Object.values(node)) {
    const hit = findPinObject(v, depth + 1);
    if (hit) return hit;
  }
  return null;
}

function decodePinId(b64) {
  try {
    const s = Buffer.from(String(b64), "base64").toString("utf8");
    const m = s.match(/(\d{6,25})/);
    return m ? m[1] : null;
  } catch {
    return null;
  }
}

function extractVideoUrls(videos) {
  const urls = [];
  const seen = new Set();
  (function walk(n, d) {
    if (!n || typeof n !== "object" || d > 6) return;
    if (typeof n.url === "string" && /\.mp4($|\?)/.test(n.url) && !seen.has(n.url)) {
      seen.add(n.url);
      urls.push({
        url: n.url,
        width: typeof n.width === "number" ? n.width : null,
        height: typeof n.height === "number" ? n.height : null,
        duration: typeof n.duration === "number" ? n.duration : null,
      });
    }
    for (const v of Object.values(n)) walk(v, d + 1);
  })(videos, 0);
  urls.sort((a, b) => (b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0));
  return urls;
}

function extractHlsUrls(root) {
  const urls = [];
  const seen = new Set();
  (function walk(n, d) {
    if (!n || typeof n !== "object" || d > 6) return;
    if (typeof n.url === "string" && /\.m3u8($|\?)/.test(n.url) && !seen.has(n.url)) {
      seen.add(n.url);
      urls.push(n.url);
    }
    for (const v of Object.values(n)) walk(v, d + 1);
  })(root, 0);
  return urls;
}

function shapePin(pin, numericId) {
  const images = {};
  for (const key of Object.keys(pin)) {
    const m = key.match(/^images_(.+)$/);
    if (m && pin[key] && pin[key].url) {
      images[m[1]] = {
        url: pin[key].url,
        width: pin[key].width || null,
        height: pin[key].height || null,
      };
    }
  }
  const original = images.orig || null;
  const videoRoots = [];
  if (pin.videos) videoRoots.push(pin.videos);
  (function collectVideoLists(n, d) {
    if (!n || typeof n !== "object" || d > 8) return;
    if (Array.isArray(n)) {
      for (const v of n) collectVideoLists(v, d + 1);
      return;
    }
    for (const key of Object.keys(n)) {
      if (/^videoList/i.test(key) && n[key]) videoRoots.push(n[key]);
      else collectVideoLists(n[key], d + 1);
    }
  })(pin, 0);
  const videos = extractVideoUrls(videoRoots);
  const hlsList = videos.length ? [] : extractHlsUrls(videoRoots);
  const isVideoPin = videos.length > 0 || hlsList.length > 0;
  const creator = pin.nativeCreator || pin.pinner || {};
  return {
    id: numericId || decodePinId(pin.id) || null,
    type: isVideoPin ? "video" : "image",
    title: pin.title || pin.gridTitle || "",
    description: pin.description || pin.gridDescription || "",
    link: pin.link || null,
    domain: pin.domain || null,
    images,
    download: {
      image: original ? original.url : pin.imageLargeUrl || null,
      video: videos.length ? videos[0].url : null,
    },
    videos,
    hls: hlsList,
    dominantColor: pin.dominantColor || null,
    saves: typeof pin.repinCount === "number" ? pin.repinCount : null,
    createdAt: pin.createdAt || null,
    author: {
      username: creator.username || null,
      fullName: creator.fullName || null,
      id: creator.entityId || decodePinId(creator.id) || null,
    },
    board: pin.board
      ? {
          name: pin.board.name || null,
          url: pin.board.url ? `https://www.pinterest.com${pin.board.url}` : null,
        }
      : null,
  };
}

function parsePinId(input) {
  const s = String(input || "").trim();
  const m = s.match(/pinterest\.[a-z.]+\/pin\/(\d{6,25})/i);
  if (m) return { id: m[1], needsResolve: false };
  if (/^\d{6,25}$/.test(s)) return { id: s, needsResolve: false };
  if (/pin\.it\//i.test(s) || /pinterest\./i.test(s)) return { id: null, needsResolve: true, url: s };
  return { id: null, needsResolve: false };
}

async function getPin(input) {
  const parsed = parsePinId(input);
  if (!parsed.id && !parsed.needsResolve) {
    throw new Error("Invalid Pinterest pin URL or ID");
  }
  let lastError = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt > 0) await new Promise((r) => setTimeout(r, 1000));
    const jar = new Jar();
    let pinUrl;
    try {
      if (parsed.needsResolve) {
        const r = await fetchText(parsed.url, jar);
        const m = r.finalUrl.match(/\/pin\/(\d{6,25})/);
        if (!m) throw new Error("Could not resolve this Pinterest link to a pin");
        pinUrl = `https://www.pinterest.com/pin/${m[1]}/`;
      } else {
        pinUrl = `https://www.pinterest.com/pin/${parsed.id}/`;
      }
      const page = await fetchText(pinUrl, jar);
      for (const resp of relayResponses(page.text)) {
        const pin = findPinObject(resp, 0);
        if (pin) {
          const numericId = (pinUrl.match(/\/pin\/(\d{6,25})/) || [])[1] || null;
          const data = shapePin(pin, numericId);
          if (!data.videos.length) {
            const htmlMp4s = [
              ...new Set(
                [...page.text.matchAll(/https:\/\/v1\.pinimg\.com\/videos\/iht\/expMp4\/[^"\\\s]+\.mp4/g)].map(
                  (m) => m[0].replace(/\\\//g, "/")
                )
              ),
            ];
            const widthOf = (u) => parseInt((u.match(/_(\d+)w\.mp4/i) || [])[1] || "0", 10);
            htmlMp4s.sort((a, b) => widthOf(b) - widthOf(a));
            if (htmlMp4s.length) {
              const best = htmlMp4s[0];
              const w = widthOf(best);
              data.videos = [{ url: best, width: w || null, height: null, duration: null }];
              data.download.video = best;
              data.type = "video";
            } else if (/v1\.pinimg\.com\/videos\/[^"\\\s]+\.m3u8/.test(page.text)) {
              throw new Error(
                "no progressive MP4 found for this pin (it may be HLS-only, private, or deleted)"
              );
            }
          }
          data.url = pinUrl;
          return data;
        }
      }
      lastError = new Error(
        "Could not extract this pin — it may be deleted, or Pinterest changed its page format"
      );
    } catch (e) {
      lastError = e;
    }
  }
  throw lastError;
}

module.exports = async function fetchSelf(url) {
  try {
    if (!url || typeof url !== "string" || !url.trim()) {
      throw new Error("Invalid Pinterest pin URL or ID");
    }
    const pin = await getPin(url.trim());

    const title = pin.title && pin.title.trim() ? pin.title.trim() : "Pinterest Pin";
    const id = pin.id || null;

    if (pin.type === "video") {
      const best = pin.videos && pin.videos.length ? pin.videos[0] : null;
      const videoUrl = cleanUrl(pin.download.video || (best && best.url));
      if (!videoUrl) {
        throw new Error(
          "no progressive MP4 found for this pin (it may be HLS-only, private, or deleted)"
        );
      }
      return {
        success: true,
        source: "Pinterest",
        data: {
          id,
          title,
          download: {
            video: videoUrl,
            image: null,
            type: "mp4",
            quality: best && best.width ? `${best.width}w` : null,
            note: "Progressive MP4 with muxed audio, extracted from the pin page",
          },
        },
      };
    }

    const imgUrl = cleanUrl(pin.download.image);
    if (!imgUrl) {
      throw new Error("no image URL found for this pin (it may be private or deleted)");
    }
    return {
      success: true,
      source: "Pinterest",
      data: {
        id,
        title,
        download: {
          video: imgUrl,
          image: imgUrl,
          type: "image",
          quality: null,
          note: null,
        },
      },
    };
  } catch (e) {
    if (/^Pinterest Error:/.test(e.message)) throw e;
    throw new Error("Pinterest Error: " + e.message);
  }
};
